/**
 * n8n Code Node – HTML-Wetterbericht
 *
 * Input: Open-Meteo Forecast API
 * Output: HTML-Datei als Binary-Output
 *
 * Einstellungen:
 * Language: JavaScript
 * Mode: Run Once for All Items
 *
 * Keine externen Bibliotheken erforderlich.
 */

// ========================================
// 1. KONFIGURATION
// ========================================

// Name deiner Geocoding-Node (optional)
const GEOCODING_NODE_NAME = "Ort -> Geocode";

// Sprache und Formatierung
const LOCALE = "de-DE";

// ========================================
// 2. HILFSFUNKTIONEN
// ========================================

function num(value, decimals = 0) {
  if (value === null || value === undefined ||
      !Number.isFinite(Number(value))) return "–";

  return Number(value).toLocaleString(LOCALE, {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

function safe(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function dateLabel(date, options = {}) {
  if (!date) return "–";

  const d = new Date(date.slice(0, 10) + "T12:00:00Z");

  if (Number.isNaN(d.getTime())) return safe(date);

  return new Intl.DateTimeFormat(LOCALE, {
    timeZone: "UTC",
    ...options,
  }).format(d);
}

function hour(time) {
  return time ? time.slice(11, 16) : "–";
}

function weather(code) {
  const c = Number(code);

  if (c === 0)
    return { icon: "☀️", text: "Sonnig" };

  if (c === 1)
    return { icon: "🌤️", text: "Überwiegend klar" };

  if (c === 2)
    return { icon: "⛅", text: "Teilweise bewölkt" };

  if (c === 3)
    return { icon: "☁️", text: "Bedeckt" };

  if (c === 45 || c === 48)
    return { icon: "🌫️", text: "Nebel" };

  if ([51, 53, 55, 56, 57].includes(c))
    return { icon: "🌦️", text: "Nieselregen" };

  if ([61, 63, 65, 66, 67].includes(c))
    return { icon: "🌧️", text: "Regen" };

  if ([71, 73, 75, 77].includes(c))
    return { icon: "❄️", text: "Schnee" };

  if ([80, 81, 82].includes(c))
    return { icon: "🌦️", text: "Regenschauer" };

  if ([85, 86].includes(c))
    return { icon: "🌨️", text: "Schneeschauer" };

  if ([95, 96, 99].includes(c))
    return { icon: "⛈️", text: "Gewitter" };

  return { icon: "🌡️", text: "Wetterdaten" };
}

function windDirection(deg) {
  if (deg === null || deg === undefined) return "–";

  const directions = [
    "N", "NO", "O", "SO", "S", "SW", "W", "NW"
  ];

  return directions[
    Math.round(Number(deg) / 45) % 8
  ];
}

function metric(label, value, unit, icon) {
  return `
    <div class="metric">
      <div class="metric-icon">${icon}</div>
      <div class="metric-label">${safe(label)}</div>
      <div class="metric-value">
        ${safe(value)}
        <span>${safe(unit)}</span>
      </div>
    </div>
  `;
}

function getCity(data, index) {
  if (data.city) return String(data.city);
  if (data.city_name) return String(data.city_name);
  if (data.location?.name) return String(data.location.name);
  if (data.name) return String(data.name);

  try {
    const geoItems = $(GEOCODING_NODE_NAME).all();
    const geo = geoItems[index]?.json || geoItems[0]?.json;
    const result = geo?.results?.[0];

    if (result?.name) {
      return result.name;
    }
  } catch (error) {
    // Geocoding-Node nicht vorhanden
  }

  return `${num(data.latitude, 3)}° N, ${num(data.longitude, 3)}° O`;
}

// ========================================
// 3. SVG-TEMPERATURDIAGRAMM
// ========================================

function temperatureChart(hourly, currentTime) {
  const times = hourly.time || [];
  const temperatures = hourly.temperature_2m || [];

  let start = times.findIndex(t => t >= currentTime);

  if (start < 0) start = 0;

  const points = [];

  for (let i = start; i < Math.min(start + 24, times.length); i++) {
    const temp = Number(temperatures[i]);

    if (Number.isFinite(temp)) {
      points.push({
        time: times[i],
        temp,
        rain: hourly.precipitation_probability?.[i] ?? null,
        code: hourly.weather_code?.[i],
      });
    }
  }

  if (points.length < 2) {
    return "<p>Keine ausreichenden Stundendaten vorhanden.</p>";
  }

  const W = 900;
  const H = 270;
  const LEFT = 48;
  const RIGHT = 22;
  const TOP = 25;
  const BOTTOM = 45;

  const plotW = W - LEFT - RIGHT;
  const plotH = H - TOP - BOTTOM;

  const values = points.map(p => p.temp);

  const minTemp = Math.floor(Math.min(...values) - 2);
  const maxTemp = Math.ceil(Math.max(...values) + 2);
  const range = Math.max(1, maxTemp - minTemp);

  function x(i) {
    return LEFT + (i / (points.length - 1)) * plotW;
  }

  function y(temp) {
    return TOP + ((maxTemp - temp) / range) * plotH;
  }

  const line = points.map((p, i) =>
    `${x(i).toFixed(1)},${y(p.temp).toFixed(1)}`
  ).join(" ");

  const area = `
    ${LEFT},${TOP + plotH}
    ${line}
    ${x(points.length - 1)},${TOP + plotH}
  `;

  let grid = "";

  for (let i = 0; i <= 4; i++) {
    const value = minTemp + (range / 4) * i;
    const yy = y(value);

    grid += `
      <line
        x1="${LEFT}" y1="${yy}"
        x2="${W - RIGHT}" y2="${yy}"
        stroke="#e5ebf2"
        stroke-dasharray="4 6"
      />
      <text
        x="8" y="${yy + 4}"
        font-size="12" fill="#8190a5"
      >${num(value)}°</text>
    `;
  }

  let labels = "";

  points.forEach((p, i) => {
    if (i % 4 !== 0 && i !== points.length - 1) return;

    labels += `
      <text
        x="${x(i)}"
        y="${H - 12}"
        text-anchor="middle"
        font-size="12"
        fill="#8190a5"
      >${hour(p.time)}</text>
    `;
  });

  const dots = points.map((p, i) => `
    <circle
      cx="${x(i)}"
      cy="${y(p.temp)}"
      r="3.5"
      fill="#2778dc"
      stroke="#ffffff"
      stroke-width="2"
    >
      <title>${hour(p.time)} – ${num(p.temp, 1)} °C</title>
    </circle>
  `).join("");

  return `
    <svg
      class="temp-chart"
      viewBox="0 0 ${W} ${H}"
      role="img"
      aria-label="Temperaturverlauf der nächsten 24 Stunden"
    >
      <defs>
        <linearGradient id="tempFill" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#438de2" stop-opacity=".28"/>
          <stop offset="100%" stop-color="#438de2" stop-opacity="0"/>
        </linearGradient>
      </defs>

      ${grid}

      <polygon
        points="${area.trim()}"
        fill="url(#tempFill)"
      />

      <polyline
        points="${line}"
        fill="none"
        stroke="#2778dc"
        stroke-width="3.5"
        stroke-linecap="round"
        stroke-linejoin="round"
      />

      ${dots}
      ${labels}
    </svg>
  `;
}

// ========================================
// 4. STÜNDLICHE VORHERSAGE
// ========================================

function hourlyForecast(hourly, currentTime) {
  const times = hourly.time || [];

  let start = times.findIndex(t => t >= currentTime);
  if (start < 0) start = 0;

  let cards = "";

  for (
    let i = start;
    i < Math.min(start + 24, times.length);
    i += 2
  ) {
    const w = weather(hourly.weather_code?.[i]);

    cards += `
      <div class="hour-card">
        <div class="hour-time">${hour(times[i])}</div>
        <div class="hour-icon">${w.icon}</div>
        <div class="hour-temp">
          ${num(hourly.temperature_2m?.[i])}°
        </div>
        <div class="hour-rain">
          💧 ${num(hourly.precipitation_probability?.[i])}%
        </div>
      </div>
    `;
  }

  return cards || "<p>Keine Stundendaten vorhanden.</p>";
}

// ========================================
// 5. 7-TAGE-VORHERSAGE
// ========================================

function dailyForecast(daily, currentDate) {
  const dates = daily.time || [];

  return dates.map((date, i) => {
    const w = weather(daily.weather_code?.[i]);

    const dayName = date === currentDate
      ? "Heute"
      : dateLabel(date, { weekday: "long" });

    const max = daily.temperature_2m_max?.[i];
    const min = daily.temperature_2m_min?.[i];
    const rain = daily.precipitation_probability_max?.[i];
    const rainMM = daily.precipitation_sum?.[i];

    return `
      <div class="day-row">
        <div class="day-name">
          <strong>${safe(dayName)}</strong>
          <small>${dateLabel(date, {
            day: "2-digit",
            month: "2-digit"
          })}</small>
        </div>

        <div class="day-weather">
          <span class="day-icon">${w.icon}</span>
          <span>${w.text}</span>
        </div>

        <div class="day-rain">
          💧 ${num(rain)}%
          <small>${num(rainMM, 1)} mm</small>
        </div>

        <div class="day-temps">
          <strong>${num(max)}°</strong>
          <span>${num(min)}°</span>
        </div>
      </div>
    `;
  }).join("");
}

// ========================================
// 6. WETTER-ZUSAMMENFASSUNG
// ========================================

function summary(current, daily) {
  const w = weather(current.weather_code);
  const parts = [];

  parts.push(`Aktuell ist es ${w.text.toLowerCase()}.`);

  if (current.temperature_2m != null) {
    parts.push(
      `Die Temperatur beträgt ${num(current.temperature_2m, 1)} °C.`
    );
  }

  if (current.apparent_temperature != null) {
    parts.push(
      `Gefühlt sind es ${num(current.apparent_temperature, 1)} °C.`
    );
  }

  const rain = daily.precipitation_probability_max?.[0];

  if (rain != null) {
    if (rain >= 60) {
      parts.push("Heute besteht eine erhöhte Regenwahrscheinlichkeit.");
    } else if (rain >= 30) {
      parts.push("Zeitweise ist Regen möglich.");
    } else {
      parts.push("Die Regenwahrscheinlichkeit ist heute eher gering.");
    }
  }

  const wind = current.wind_speed_10m;

  if (wind >= 40) {
    parts.push("Es ist mit kräftigem Wind zu rechnen.");
  } else if (wind >= 20) {
    parts.push("Der Wind ist deutlich spürbar.");
  }

  return parts.join(" ");
}

// ========================================
// 7. HTML ERZEUGEN
// ========================================

function createReport(data, city) {
  const current = data.current || {};
  const hourly = data.hourly || {};
  const daily = data.daily || {};

  const now = current.time || daily.time?.[0] || "";
  const currentDate = now.slice(0, 10);

  const w = weather(current.weather_code);

  const sunrise = daily.sunrise?.[0];
  const sunset = daily.sunset?.[0];
  const sunshine = daily.sunshine_duration?.[0];

  const generatedDate = dateLabel(currentDate, {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });

  const html = `<!DOCTYPE html>
