<script>
function downloadReport() {
  const html = "<!DOCTYPE html>\\n" +
    document.documentElement.outerHTML;

  const blob = new Blob([html], {
    type: "text/html;charset=utf-8"
  });

  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");

  link.href = url;
  link.download = document.title
    .replace(/[^a-zA-Z0-9äöüÄÖÜß_-]+/g, "_") + ".html";

  document.body.appendChild(link);
  link.click();
  link.remove();

  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
</script>

</body>
</html>`;

  return html;
}

// ========================================
// 8. N8N INPUT VERARBEITEN
// ========================================

const items = $input.all();

const output = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index];

  let data = item.json;

  // Verschiedene JSON-Strukturen unterstützen
  if (Array.isArray(data)) {
    data = data[0];
  }

  if (Array.isArray(data?.body)) {
    data = data.body[0];
  } else if (data?.body?.current) {
    data = data.body;
  }

  if (!data || !data.current) {
    throw new Error(
      `Item ${index + 1}: Keine gültigen Open-Meteo-Daten gefunden.`
    );
  }

  const city = getCity(data, index);

  // HTML generieren
  const html = createReport(data, city);

  // Dateiname bereinigen
  const safeCity = city
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9_-]+/g, "_")
    .slice(0, 50);

  const date = (data.current.time || "")
    .slice(0, 10) || "wetter";

  const filename = `Wetterbericht_${safeCity}_${date}.html`;

  // HTML als Base64-Binary
  const base64 = Buffer.from(
    html,
    "utf8"
  ).toString("base64");

  output.push({
    json: {
      city,
      date,
      filename,
      latitude: data.latitude,
      longitude: data.longitude,
      temperature: data.current.temperature_2m,
      description: weather(
        data.current.weather_code
      ).text,
      status: "HTML-Wetterbericht erfolgreich erstellt",
    },

    binary: {
      report: {
        data: base64,
        mimeType: "text/html",
        fileName: filename,
        fileExtension: "html",
      }
    }
  });
}

// ========================================
// 9. ERGEBNIS ZURÜCKGEBEN
// ========================================

return output;
